@namespace sv_47a2d94407a04f119934da4322fe8501.Components.Pages.Chat
@using sv_47a2d94407a04f119934da4322fe8501.Services

<aside class="channel-list">
    <h2 class="channel-list-header">Channels</h2>
    @foreach (var channel in Channels)
    {
        <div class="channel-item @(channel.Id == SelectedChannelId ? "active" : "")"
             @onclick="() => OnChannelSelected.InvokeAsync(channel.Id)">
            <div class="channel-name"># @channel.Name</div>
            <div class="channel-description">@TruncateDescription(channel.Description)</div>
            @if (channel.UnreadCount > 0)
            {
                <span class="unread-badge">@channel.UnreadCount</span>
            }
        </div>
    }
</aside>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnChannelSelected { get; set; }

    private static string TruncateDescription(string description)
    {
        return description.Length > 40 ? description[..37] + "..." : description;
    }
}

@namespace sv_47a2d94407a04f119934da4322fe8501.Components.Pages.Chat
@using sv_47a2d94407a04f119934da4322fe8501.Services
@inject IJSRuntime JS

<section class="message-area">
    <header class="message-area-header">
        <h2># @ChannelName</h2>
        <p>@ChannelDescription</p>
    </header>

    <div class="message-list" @ref="_messageListRef" @onscroll="HandleScroll">
        @if (_isLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }
        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ReplyCount="GetReplyCount(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")" ButtonText="Send" OnSubmit="OnSendMessage" />
</section>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = string.Empty;
    [Parameter] public string ChannelDescription { get; set; } = string.Empty;
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingMore { get => _isLoadingMore; set => _isLoadingMore = value; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference _messageListRef;
    private bool _isLoadingMore;

    private int GetReplyCount(int messageId)
    {
        return ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId)?.ReplyCount ?? 0;
    }

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list').scrollTop");
        if (scrollTop <= 50 && !_isLoadingMore)
        {
            await OnLoadMore.InvokeAsync();
        }
    }
}

@namespace sv_47a2d94407a04f119934da4322fe8501.Components.Pages.Chat
@using sv_47a2d94407a04f119934da4322fe8501.Services

<aside class="thread-panel">
    <header class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">&times;</button>
    </header>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <span class="message-author">@RootMessage.Author</span>
            <p class="message-content">@RootMessage.Content</p>
        </div>

        <div class="thread-replies">
            @foreach (var reply in ThreadMessages)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply in thread..." ButtonText="Reply" OnSubmit="OnReply" />
    }
</aside>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> ThreadMessages { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnClose { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
