{"file_text": "@page "/chat"
@namespace sv_47a2d94407a04f119934da4322fe8501.Components.Pages.Chat
@using sv_47a2d94407a04f119934da4322fe8501.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout @(_threadOpen ? "thread-open" : "")">
    <ChannelList Channels="_channels"
                 SelectedChannelId="_selectedChannelId"
                 OnChannelSelected="HandleChannelSelected" />

    <MessageArea ChannelName="@_currentChannelName"
                 ChannelDescription="@_currentChannelDescription"
                 Messages="_messages"
                 ThreadSummaries="_threadSummaries"
                 IsLoadingMore="_isLoadingMore"
                 OnOpenThread="HandleOpenThread"
                 OnReact="HandleReact"
                 OnSendMessage="HandleSendMessage"
                 OnLoadMore="HandleLoadMore" />

    @if (_threadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     ThreadMessages="_threadMessages"
                     OnClose="HandleCloseThread"
                     OnReply="HandleThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private List<Message> _messages = [];
    private List<ThreadSummary> _threadSummaries = [];
    private List<Message> _threadMessages = [];
    private Message? _threadRootMessage;

    private int _selectedChannelId;
    private string _currentChannelName = string.Empty;
    private string _currentChannelDescription = string.Empty;
    private bool _threadOpen;
    private bool _isLoadingMore;
    private int _messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task HandleChannelSelected(int channelId)
    {
        await SelectChannel(channelId);
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _messageSkip = 0;
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];

        var channel = _channels.First(c => c.Id == channelId);
        _currentChannelName = channel.Name;
        _currentChannelDescription = channel.Description;

        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messageSkip = _messages.Count;

        // Build thread summaries from messages that have replies
        _threadSummaries = _messages
            .Where(m => m.ReplyToId is null)
            .Select(m => new { RootId = m.Id, Replies = _messages.Where(r => r.ReplyToId == m.Id).ToList() })
            .Where(x => x.Replies.Count > 0)
            .Select(x => new ThreadSummary(x.RootId, x.Replies.Count, x.Replies.Max(r => r.SentAt)))
            .ToList();

        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task HandleLoadMore()
    {
        if (_isLoadingMore) return;
        _isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(_selectedChannelId, _messageSkip, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messageSkip += older.Count;
        }

        _isLoadingMore = false;
    }

    private async Task HandleSendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(_selectedChannelId, content, null);
        _messages.Add(message);
    }

    private async Task HandleOpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        _threadMessages = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private Task HandleCloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = [];
        return Task.CompletedTask;
    }

    private async Task HandleReact((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Update local state
        var msg = _messages.FirstOrDefault(m => m.Id == args.MessageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
        }
    }

    private async Task HandleThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootMessage.Id);
        _threadMessages.Add(reply);

        // Update thread summary
        var existing = _threadSummaries.FindIndex(t => t.RootMessageId == _threadRootMessage.Id);
        if (existing >= 0)
        {
            _threadSummaries[existing] = _threadSummaries[existing] with
            {
                ReplyCount = _threadSummaries[existing].ReplyCount + 1,
                LastReplyAt = reply.SentAt
            };
        }
        else
        {
            _threadSummaries.Add(new ThreadSummary(_threadRootMessage.Id, 1, reply.SentAt));
        }
    }
}
