+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+
+        // Update local state
+        var msg = _messages.FirstOrDefault(m => m.Id == args.MessageId);
+        if (msg is not null)
+        {
+            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == args.Emoji);
+            if (existing is not null)
+            {
+                existing.Users.Add("You");
+            }
+            else
+            {
+                msg.Reactions.Add(new Reaction(args.Emoji, ["You"]));
+            }
+        }
+    }
+
+    private async Task HandleThreadReply(string content)
+    {
+        if (_threadRootMessage is null) return;
+        var reply = await ChatService.SendMessageAsync(_selectedChannelId, content, _threadRootMessage.Id);
+        _threadMessages.Add(reply);
+
+        // Update thread summary
+        var existing = _threadSummaries.FindIndex(t => t.RootMessageId == _threadRootMessage.Id);
+        if (existing >= 0)
+        {
+            _threadSummaries[existing] = _threadSummaries[existing] with
+            {
+                ReplyCount = _threadSummaries[existing].ReplyCount + 1,
+                LastReplyAt = reply.SentAt
+            };
+        }
+        else
+        {
+            _threadSummaries.Add(new ThreadSummary(_threadRootMessage.Id, 1, reply.SentAt));
+        }
+    }
+}
